function openClearEverything(){
 showDialog('Clear everything?',`<div class="erase-warning"><strong>THIS ERASES ALL SAVED APP DATA ON THIS DEVICE</strong><p>The current run, event log, weight, timers, team names and colors, and saved preferences will be removed.</p><p>Export your PDF first. Downloaded PDFs will remain on your device. This cannot be undone.</p></div><label class="check"><input id="confirm-erase" type="checkbox" required> I understand that all saved app data will be permanently erased.</label>`,'Yes, erase everything');
 $('#entry-form .performer-control')?.remove();$('#dialog').classList.add('erase-dialog');$('#entry-form .primary').disabled=true;
 $('#confirm-erase').onchange=()=>{modalContext.dirty=false;$('#entry-form .primary').disabled=!$('#confirm-erase').checked;};
 $('#entry-form').onsubmit=async e=>{e.preventDefault();if(!$('#confirm-erase').checked)return;const button=$('#entry-form .primary');button.disabled=true;button.textContent='Erasing…';try{await saveChain;const clean=initial();const store=sessionStore||await openSessionStore();saveRevision=await store.reset(clean);sessionStore=store;state=clean;lastSnapshot=JSON.stringify(state);savePending=0;storageConflict=false;storageReady=true;saveMessage='Saved data cleared';quickTaps.clear();if(lastPDF)URL.revokeObjectURL(lastPDF);lastPDF=null;$('#dialog').close();modalContext=null;render();toast('All saved app data cleared.');}catch(err){fail(Error('Could not erase saved data. '+err.message));button.disabled=false;button.textContent='Yes, erase everything';}};
}
function storageStatus(){const el=$('#save-status');if(el)el.textContent=saveMessage;}
function autosave(){
 if(!storageReady||!sessionStore||storageConflict)return;
 const snapshot=JSON.stringify(state);if(snapshot===lastSnapshot)return;lastSnapshot=snapshot;savePending++;saveMessage='Saving on this device…';storageStatus();
 saveChain=saveChain.then(async()=>{if(storageConflict)return;try{saveRevision=await sessionStore.write(JSON.parse(snapshot),saveRevision);saveMessage='Saved on this device';}catch(e){lastSnapshot='';storageConflict=true;saveMessage=e.name==='SessionConflict'?e.message:'Local save failed · export PDF before leaving';}finally{savePending--;storageStatus();}});
}
async function initializeSession(){
 try{sessionStore=await openSessionStore();const saved=await sessionStore.read();if(saved){saveRevision=saved.revision;state={...initial(),...saved.state};lastSnapshot=JSON.stringify(state);}saveMessage='Saved on this device';render();
 if(saved&&(state.events.length||state.run['Weight (kg)']||state.run['Run name / number']||Object.keys(state.doseDrafts).length||state.weightDraft)){
  showDialog('Saved run found',`<p><strong>${esc(state.run['Run name / number']||'Unnamed run')}</strong> · ${state.events.filter(e=>e.type!=='Correction').length} entries</p><p>Last saved ${esc(new Date(saved.savedAt).toLocaleString())}. Running timers include time while the app was closed.</p><p>Your team roster stays available when starting a new run.</p><div class="secondary-actions"><button type="button" id="resume-saved">Resume run</button><button type="button" id="new-saved">Start new run</button></div>`);
  $('#entry-form .performer-control')?.remove();$('#entry-form .modal-foot').remove();$('#dialog').querySelectorAll('[data-close]').forEach(b=>b.remove());$('#dialog').oncancel=e=>e.preventDefault();$('#entry-form').onsubmit=e=>e.preventDefault();
  $('#resume-saved').onclick=()=>{storageReady=true;$('#dialog').close();modalContext=null;render();if(state.start&&!state.end)requestWake();};
  $('#new-saved').onclick=()=>{storageReady=true;$('#dialog').close();modalContext=null;act('clear');};
 }else{storageReady=true;render();}
 }catch(e){sessionStore=null;saveMessage='Local saving unavailable · export PDF before leaving';storageReady=true;render();toast(e.message);}
}
