function quickCPRHTML(c){return `<section class="quick-cpr" aria-label="Quick CPR controls"><div class="cpr-state"><span class="eyebrow">CPR</span><strong>${c.active?'Active':c.paused?'Paused':'Not active'}</strong></div><button class="primary" data-action="cpr-start" ${c.active||state.end?'disabled':''}>${c.paused?'Resume CPR':'Start CPR'}</button><button data-action="cpr-pause" ${!c.active||state.end?'disabled':''}>Pause CPR</button><button class="stop-cpr" data-action="cpr-stop" ${(!c.active&&!c.paused)||state.end?'disabled':''}>Stop CPR</button></section>`;}
function quickReceipt(){const e=effective().find(e=>e.id===state.quickEvent);return e?`<div class="quick-receipt" role="status"><span><strong>${esc(eventTitle(e))}</strong> logged ${clock(e.t)} · ${esc(e.data['Performed by'])}</span><button class="small" data-detail="${e.id}">${e.type==='Medication'?'Add details (optional)':e.data['Details status']==='Added'?'Edit details':'Add details'}</button><button class="small" data-undo="${e.id}">Undo</button></div>`:'';}
const quickTaps=new Map();
function quickAction(action){
 if(!canRecord())return;const now=Date.now();if(now-(quickTaps.get(action)||0)<700)return;quickTaps.set(action,now);
 const c=activeCPR();let type,data={'Quick entry':'Yes','Details status':'Pending','Time certainty':'Actual'};
 if(action==='cpr-start'){if(c.active)return;type=c.paused?'CPR resumed':'CPR started';if(c.paused)data['Interruption duration (seconds)']=fmt((now-c.paused)/1000);}
 else if(action==='cpr-pause'){if(!c.active)return;type='CPR paused';data['Interruption reason']='Not entered';}
 else if(action==='cpr-stop'){if(!c.active&&!c.paused)return;type='CPR stopped';data.Reason='Not entered';}
 else if(action==='compressor'){type='Compressor change';data['New compressor']=state.team.find(m=>m.id===state.activeActor)?.name||'Unassigned';}
 else if(action==='quick-rosc'){if(effective().filter(e=>['ROSC','Rearrest'].includes(e.type)).at(-1)?.type==='ROSC'){toast('ROSC already recorded. Add details from the log.');return;}type='ROSC';data['Evidence of circulation']='Not entered';}
 else if(action==='quick-rearrest'){type='Rearrest';data['Evidence / circumstances']='Not entered';}
 if(!type)return;const e=append(type,data,now);state.quickEvent=e.id;render();requestWake();
}
function undoQuick(id){const e=effective().find(e=>e.id===id);if(!e)return;delete state.doseDrafts[id];append('Correction',{'Original event':e.type,Reason:'Accidental quick tap - undone','Recorder initials':state.run['Recorder initials']},Date.now(),{target:id,voided:true});state.quickEvent=null;render();toast('Quick entry undone. Original retained in audit trail.');}
