function patientWeightHTML(){const d=state.weightDraft,w=d?.weight??state.run['Weight (kg)'],b=d?.basis??state.run['Weight basis'];return `<section class="patient-weight" aria-label="Patient weight"><div><h2>Patient weight</h2><p>Enter kilograms and choose measured or estimated. All medications and available dose calculations populate automatically when you finish editing. Previously recorded doses stay unchanged.</p></div><form id="patient-weight-form"><label for="patient-weight-kg">Weight (kg)</label><input id="patient-weight-kg" name="weight" type="number" min="0.000001" max="500" step="any" inputmode="decimal" placeholder="kg" value="${esc(w)}" required ${state.end?'disabled':''}><label for="patient-weight-basis">Weight basis</label><select id="patient-weight-basis" name="basis" required ${state.end?'disabled':''}><option value="">Choose basis</option>${['Measured','Estimated'].map(x=>`<option ${b===x?'selected':''}>${x}</option>`).join('')}</select><p id="patient-weight-status" role="status">${d?'Finish editing a valid weight and choose its basis to update doses.':state.run['Weight (kg)']?`Using ${esc(state.run['Weight (kg)'])} kg · ${esc(state.run['Weight basis'])}`:'Enter weight for weight-based doses.'}</p></form><div id="weight-dose-preview">${weightDosePreview()}</div></section>`;}
