function effective(){return state.events.filter(e=>e.type!=='Correction').map(e=>{const c=state.events.filter(x=>x.type==='Correction'&&x.target===e.id).at(-1);return c?{...e,t:c.correctedTime??e.t,data:c.replacement??e.data,voided:c.voided,correction:c.id}:e;}).filter(e=>!e.voided).sort((a,b)=>a.t-b.t||a.entered-b.entered);}
